from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    dp = [[float('inf')] * n for _ in range(n)]

    # Initialize the first row and column
    for i in range(n):
        dp[0][i] = grid[0][i]
        dp[i][0] = grid[i][0]

    # Fill the DP table
    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    # Find the shortest path of length k
    for i in range(k+1):
        for j in range(k-i+1):
            for l in range(j, k-i+j):
                if dp[k-1][l] == float('inf'):
                    break
                dp[k-1][k-l-1] = min(dp[k-1][k-l-1], dp[k-1][l])

    return dp[-1][-1]
