def eulerian_num(n, m):
    # Base case: if n is less than m, return 0
    if n < m:
        return 0

    # Initialize the first row of Pascal's triangle
    pascal = [[1] * (i + 1) for i in range(m)]

    # Fill Pascal's triangle up to the nth row
    for i in range(2, n + 1):
        for j in range(1, i):
            pascal[i][j] = pascal[i - 1][j - 1] + pascal[i - 1][j]

    # Calculate the Eulerian number using Pascal's triangle values
    eulerian = 0
    for i in range(m):
        eulerian += pascal[n][i] * pow(-1, i)

    return int(eulerian)

