def max_sum(arr):
    n = len(arr)

    # Initialize variables to store the maximum sums
    inc = [arr[0]] * n
    dec = [arr[-1]] * n

    # Calculate the maximum sum for each element as part of an increasing subsequence
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Calculate the maximum sum for each element as part of a decreasing subsequence
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # The answer will be the maximum value from both lists (increasing and decreasing subsequences)
    return max(max(inc), max(dec))

