def find_kth(arr1, arr2, k):
    # Find the position of the k-th smallest number
    pos = (k - 1) // len(arr1)

    # Calculate the values at the found positions in both arrays
    val1 = arr1[pos] if pos < len(arr1) else float('inf')
    val2 = arr2[pos] if pos < len(arr2) else float('inf')

    # If the value in arr1 is less than or equal to the value in arr2,
    # then it must be the k-th smallest number because all numbers before it in arr1 are smaller.
    if val1 <= val2:
        return find_kth(arr1, arr2[:pos + 1], k)
    else:
        return find_kth(arr1[:pos + 1], arr2, k - pos - 1)
```

