from typing import List

def maxAverageOfPath(costs: List[List[int]]) -> float:
    n = len(costs)

    # Initialize DP table for left and up moves
    dp_left = [[0] * (n + 1) for _ in range(n)]
    dp_up = [[0] * (n + 1) for _ in range(n)]

    # Fill the DP table for left moves
    for i in range(1, n):
        dp_left[i][1] = costs[i-1][0]
        for j in range(2, n+1):
            dp_left[i][j] = min(dp_left[i-1][j], dp_left[i][j-1]) + costs[i-1][j-2]

    # Fill the DP table for up moves
    for j in range(1, n):
        dp_up[1][j] = costs[0][j-1]
        for i in range(2, n+1):
            dp_up[i][j] = min(dp_up[i-1][j], dp_up[i][j-1]) + costs[i-2][j-1]

    # Calculate the maximum average path
    max_avg = -float('inf')
    for i in range(1, n+1):
        for j in range(1, n+1):
            avg_cost = (dp_left[n-i][n-j] + dp_up[n-i][n-j]) / (i+j-1)
            if avg_cost > max_avg:
                max_avg = avg_cost

    return max_avg
```

