    if n == 0: 
        return 0
    elif n == 1: 
        return 1

    # Initialize variables for memoization
    @lru_cache(None)
    def helper(j): 
        if j == 0: 
            return 0
        elif j == 1: 
            return 1

        # Recursive calls with memoized results
        return (helper(j-1) + 2 * helper(j-2))

    # Calculate Jacobsthal number using helper function
    return helper(n)

