def get_pairs_count(nums, target):
    # Create a dictionary to store the frequency of each number
    freq = {}

    # Count the occurrences of each number in the list
    for num in nums:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Initialize the count of pairs with the same value
    count = 0

    # Iterate through the frequencies
    for key, val in freq.items():
        complement = target - key

        # If the complement exists in the dictionary, add its frequency to the count
        if complement in freq:
            count += val * freq[complement]

    return count
```

