def find_sum(lst):
    # Calculate the XOR of all numbers and their indices
    xor = 0
    for i, num in enumerate(lst):
        xor ^= (num << i)

    # Find the first set bit position
    pos = -1
    while not xor & 1:
        xor >>= 1

    # Split the list into two parts based on the found set bit
    left, right = [], []
    for n in lst:
        if n >> pos & 1:
            left.append(n)
        else:
            right.append(n)

    # Calculate the sum of each part and return the difference
    return sum(left) ^ sum(right)

